import React, { useState, useRef } from 'react';
import axios from 'axios';
import './EnhancedBillUpload.css';

const EnhancedBillUpload = ({ onUploadSuccess }) => {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [dragActive, setDragActive] = useState(false);
  const [processingStatus, setProcessingStatus] = useState(null);
  const fileInputRef = useRef(null);

  // Check processing status on component mount
  React.useEffect(() => {
    checkProcessingStatus();
  }, []);

  const checkProcessingStatus = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:8000/bills/processing-status', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProcessingStatus(response.data);
    } catch (error) {
      console.error('Error checking processing status:', error);
    }
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      setFile(e.dataTransfer.files[0]);
      setError(null);
      setResult(null);
    }
  };

  const handleFileSelect = (e) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setError(null);
      setResult(null);
    }
  };

  const handleUpload = async () => {
    if (!file) {
      setError('Please select a file first');
      return;
    }

    setUploading(true);
    setError(null);
    setResult(null);

    const formData = new FormData();
    formData.append('file', file);

    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:8000/upload',
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setResult(response.data);
      setFile(null);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
      
      // Call the success callback if provided
      if (onUploadSuccess) {
        onUploadSuccess(response.data);
      }
    } catch (error) {
      console.error('Upload error:', error);
      setError(
        error.response?.data?.detail || 
        'An error occurred while processing the bill'
      );
    } finally {
      setUploading(false);
    }
  };

  const formatCurrency = (amount, currency = 'INR') => {
    if (!amount) return 'N/A';
    const symbol = currency === 'INR' ? '₹' : currency === 'USD' ? '$' : currency;
    return `${symbol}${parseFloat(amount).toFixed(2)}`;
  };

  const getConfidenceColor = (score) => {
    if (score >= 0.8) return '#4CAF50'; // Green
    if (score >= 0.6) return '#FF9800'; // Orange
    return '#F44336'; // Red
  };

  const getParsingMethodBadge = (method) => {
    const badges = {
      'gemini_2_flash': { color: '#4CAF50', text: 'Gemini 2.0 Flash' },
      'regex_fallback': { color: '#FF9800', text: 'Regex Parser' },
      'gemini_regex_hybrid': { color: '#2196F3', text: 'Hybrid (AI + Regex)' },
      'enhanced': { color: '#9C27B0', text: 'Enhanced Pipeline' }
    };
    
    const badge = badges[method] || { color: '#757575', text: method || 'Unknown' };
    
    return (
      <span 
        style={{
          backgroundColor: badge.color,
          color: 'white',
          padding: '4px 8px',
          borderRadius: '12px',
          fontSize: '12px',
          fontWeight: 'bold'
        }}
      >
        {badge.text}
      </span>
    );
  };

  return (
    <div className="enhanced-bill-container">
      <div className="enhanced-bill-header">
        <h1>🚀 AI-Powered Bill Processing</h1>
        <p>Upload your bills and let our AI extract data with 90%+ accuracy</p>
      </div>

      {/* Processing Status */}
      {processingStatus && (
        <div className="processing-status-card">
          <div style={{ display: 'flex', alignItems: 'center', marginBottom: '16px' }}>
            <div
              className="processing-status-dot"
              style={{ backgroundColor: processingStatus.overall_status === 'healthy' ? '#4CAF50' : '#ff9800' }}
            ></div>
            <h3 className="processing-status-title">
              🤖 AI Processing Status: {processingStatus.overall_status.toUpperCase()}
            </h3>
          </div>
          <div className="processing-status-services">
            {/* OCR Extraction */}
            <div className="processing-service-card">
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <span style={{ fontWeight: '600', color: '#333' }}>📸 OCR Extraction</span>
                <span style={{ color: processingStatus.services.ocr_space?.available ? '#4CAF50' : '#f44336', fontWeight: 'bold' }}>
                  {processingStatus.services.ocr_space?.available ? '✅ Ready' : '❌ Offline'}
                </span>
              </div>
            </div>
            {/* Gemini AI */}
            <div className="processing-service-card">
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <span style={{ fontWeight: '600', color: '#333' }}>🧠 Gemini AI</span>
                <span style={{ color: processingStatus.services.gemini?.available ? '#4CAF50' : '#f44336', fontWeight: 'bold' }}>
                  {processingStatus.services.gemini?.available ? '✅ Ready' : '❌ Offline'}
                </span>
              </div>
            </div>
            {/* Pattern Fallback */}
            <div className="processing-service-card">
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <span style={{ fontWeight: '600', color: '#333' }}>🔍 Pattern Fallback</span>
                <span style={{ color: processingStatus.services.regex_fallback?.available ? '#4CAF50' : '#f44336', fontWeight: 'bold' }}>
                  {processingStatus.services.regex_fallback?.available ? '✅ Ready' : '❌ Offline'}
                </span>
              </div>
            </div>
          </div>
          <div className="processing-pipeline-badge">
            <span>🔄</span>
            Pipeline: {processingStatus.services.processing_pipeline}
          </div>
        </div>
      )}

      {/* File Upload Area */}
      <div
        className={`upload-area${dragActive ? ' drag-active' : ''}`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*,.pdf"
          onChange={handleFileSelect}
          style={{ display: 'none' }}
        />
        <div className="bg-icon">🤖</div>
        {file ? (
          <div className="upload-file-info">
            <div className="upload-file-icon">📄</div>
            <div className="upload-file-details">
              <p>✅ {file.name}</p>
              <p className="file-size">📊 Size: {(file.size / 1024 / 1024).toFixed(2)} MB • Ready for AI processing</p>
            </div>
          </div>
        ) : (
          <div className="upload-placeholder">
            <div className={`upload-placeholder-icon${dragActive ? ' drag-active' : ''}`}>{dragActive ? '📤' : '📁'}</div>
            <h3 className="upload-placeholder-title">{dragActive ? '🎯 Drop your bill here!' : '📤 Upload Your Bill'}</h3>
            <p className="upload-placeholder-desc">{dragActive ? 'Release to upload' : 'Drag and drop your bill here, or click to browse'}</p>
            <div className="upload-badges">
              <span className="upload-badge">🤖 AI-Powered</span>
              <span className="upload-badge">📸 JPG, PNG, PDF</span>
              <span className="upload-badge">📏 Max 10MB</span>
            </div>
          </div>
        )}
      </div>

      {/* Upload Button */}
      <div style={{ textAlign: 'center', marginBottom: '40px' }}>
        <button
          className="upload-btn-main"
          onClick={handleUpload}
          disabled={!file || uploading}
        >
          {uploading ? '🤖 AI Processing...' : '🚀 Process with AI'}
        </button>
        {file && !uploading && (
          <p className="upload-success-msg">✨ Ready to extract data with 90%+ accuracy</p>
        )}
      </div>

      {/* Error Display */}
      {error && (
        <div className="upload-error-msg">
          <div style={{ display: 'flex', alignItems: 'center', marginBottom: '12px' }}>
            <div style={{ width: '24px', height: '24px', borderRadius: '50%', backgroundColor: '#f44336', display: 'flex', alignItems: 'center', justifyContent: 'center', marginRight: '12px', fontSize: '14px' }}>❌</div>
            <span>{error}</span>
          </div>
        </div>
      )}

      {/* Results Display */}
      {result && result.success && (
        <div className="results-card">
          {/* Success decoration */}
          <div style={{
            position: 'absolute',
            top: '20px',
            right: '20px',
            fontSize: '32px',
            opacity: '0.1',
            transform: 'rotate(-15deg)'
          }}>🎉</div>
          
          <div style={{ display: 'flex', alignItems: 'center', marginBottom: '24px' }}>
            <div style={{
              width: '32px',
              height: '32px',
              borderRadius: '50%',
              backgroundColor: '#4CAF50',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              marginRight: '16px',
              fontSize: '18px',
              boxShadow: '0 4px 12px rgba(76, 175, 80, 0.3)'
            }}>✅</div>
            <h2 style={{ 
              margin: '0', 
              color: '#2e7d32', 
              fontSize: '24px', 
              fontWeight: '700'
            }}>
              {result.message}
            </h2>
          </div>
          
          {/* Processing Information */}
          <div className="processing-info-card">
            <h3 style={{ 
              margin: '0 0 16px 0', 
              color: '#2e7d32', 
              fontSize: '18px', 
              fontWeight: '600',
              display: 'flex',
              alignItems: 'center'
            }}>
              <span style={{ marginRight: '8px' }}>📊</span>
              Processing Information
            </h3>
            
            <div style={{ 
              display: 'grid', 
              gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', 
              gap: '16px',
              marginBottom: '16px'
            }}>
              <div style={{
                backgroundColor: 'white',
                padding: '16px',
                borderRadius: '12px',
                border: '1px solid #e0e0e0',
                boxShadow: '0 2px 8px rgba(0,0,0,0.05)'
              }}>
                <div style={{ fontSize: '12px', color: '#666', marginBottom: '4px', fontWeight: '600' }}>
                  METHOD
                </div>
                <div style={{ fontSize: '16px', fontWeight: '600' }}>
                  {getParsingMethodBadge(result.processing_info?.parsing_method)}
                </div>
              </div>
              
              <div style={{
                backgroundColor: 'white',
                padding: '16px',
                borderRadius: '12px',
                border: '1px solid #e0e0e0',
                boxShadow: '0 2px 8px rgba(0,0,0,0.05)'
              }}>
                <div style={{ fontSize: '12px', color: '#666', marginBottom: '4px', fontWeight: '600' }}>
                  CONFIDENCE
                </div>
                <div style={{ 
                  fontSize: '20px', 
                  fontWeight: '700',
                  color: getConfidenceColor(result.processing_info?.confidence_score)
                }}>
                  {(result.processing_info?.confidence_score * 100).toFixed(1)}%
                </div>
              </div>
              
              <div style={{
                backgroundColor: 'white',
                padding: '16px',
                borderRadius: '12px',
                border: '1px solid #e0e0e0',
                boxShadow: '0 2px 8px rgba(0,0,0,0.05)'
              }}>
                <div style={{ fontSize: '12px', color: '#666', marginBottom: '4px', fontWeight: '600' }}>
                  PROCESSING TIME
                </div>
                <div style={{ fontSize: '16px', fontWeight: '600', color: '#4CAF50' }}>
                  ⚡ {result.processing_info?.processing_time?.toFixed(2)}s
                </div>
              </div>
            </div>
            
            {result.processing_info?.validation_warnings?.length > 0 && (
              <div style={{
                backgroundColor: 'rgba(255, 152, 0, 0.1)',
                border: '1px solid rgba(255, 152, 0, 0.3)',
                borderRadius: '8px',
                padding: '12px',
                marginTop: '16px'
              }}>
                <div style={{ 
                  color: '#f57c00', 
                  fontWeight: '600',
                  fontSize: '14px',
                  display: 'flex',
                  alignItems: 'center'
                }}>
                  <span style={{ marginRight: '8px' }}>⚠️</span>
                  Validation Warnings
                </div>
                <div style={{ color: '#f57c00', fontSize: '14px', marginTop: '4px' }}>
                  {result.processing_info.validation_warnings.join(', ')}
                </div>
              </div>
            )}
          </div>

          {/* Bill Data */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '15px' }}>
            <div>
              <h4 style={{ margin: '0 0 10px 0', color: '#333' }}>Basic Information</h4>
              <div style={{ fontSize: '14px', lineHeight: '1.6' }}>
                <div><strong>Bill ID:</strong> {result.bill_data.id}</div>
                <div><strong>Date:</strong> {result.bill_data.date || 'N/A'}</div>
                <div><strong>Vendor:</strong> {result.bill_data.vendor || 'N/A'}</div>
                <div><strong>Category:</strong> {result.bill_data.category || 'N/A'}</div>
                <div><strong>Status:</strong> {result.bill_data.status}</div>
              </div>
            </div>

            <div>
              <h4 style={{ margin: '0 0 10px 0', color: '#333' }}>Financial Details</h4>
              <div style={{ fontSize: '14px', lineHeight: '1.6' }}>
                <div><strong>Amount:</strong> {formatCurrency(result.bill_data.amount, result.bill_data.currency)}</div>
                <div><strong>Subtotal:</strong> {formatCurrency(result.bill_data.subtotal, result.bill_data.currency)}</div>
                <div><strong>Tax:</strong> {formatCurrency(result.bill_data.tax, result.bill_data.currency)}</div>
                <div><strong>Discount:</strong> {formatCurrency(result.bill_data.discount, result.bill_data.currency)}</div>
                <div><strong>Currency:</strong> {result.bill_data.currency}</div>
              </div>
            </div>

            <div>
              <h4 style={{ margin: '0 0 10px 0', color: '#333' }}>Additional Details</h4>
              <div style={{ fontSize: '14px', lineHeight: '1.6' }}>
                <div><strong>Payment Method:</strong> {result.bill_data.payment_method || 'N/A'}</div>
                <div><strong>Invoice Number:</strong> {result.bill_data.invoice_number || 'N/A'}</div>
                {result.bill_data.travel_from && (
                  <div><strong>From:</strong> {result.bill_data.travel_from}</div>
                )}
                {result.bill_data.travel_to && (
                  <div><strong>To:</strong> {result.bill_data.travel_to}</div>
                )}
              </div>
            </div>
          </div>

          {result.bill_data.description && (
            <div style={{ marginTop: '15px' }}>
              <h4 style={{ margin: '0 0 10px 0', color: '#333' }}>Description</h4>
              <p style={{ margin: '0', fontSize: '14px', color: '#666', fontStyle: 'italic' }}>
                {result.bill_data.description}
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default EnhancedBillUpload;
